-- Reviewed senior batch 008; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3244,"word":"critique","meaning":"評論","example":"The teacher's thoughtful critique helped us improve the model bridge.","example_zh":"老師周到的評論幫助我們改進模型橋。","original_meaning":"評論","original_example":"The film received positive critique.","original_example_zh":"這部電影獲得了正面評價。"},{"source_id":3245,"word":"crossroads","meaning":"十字路口","example":"We met at the crossroads where the two village roads intersect.","example_zh":"我們在兩條村道交會的十字路口碰面。","original_meaning":"十字路口","original_example":"We reached a crossroads in our decision.","original_example_zh":"我們在決策上到了十字路口。"},{"source_id":3246,"word":"crucible","meaning":"坩堝","example":"The metalworker used a crucible to hold the heated metal.","example_zh":"金屬工匠用坩堝盛裝加熱的金屬。","original_meaning":"坩堝","original_example":"The metal melted in the crucible.","original_example_zh":"金屬在坩堝中熔化。"},{"source_id":3247,"word":"crusade","meaning":"運動","example":"The students began a crusade against plastic litter on the beach.","example_zh":"學生發起抵制海灘塑膠垃圾的運動。","original_meaning":"運動","original_example":"The campaign became a crusade for justice.","original_example_zh":"這場運動演變成一場正義的聖戰。"},{"source_id":3248,"word":"cultivation","meaning":"培養；栽培","example":"The cultivation of vegetables taught the students patience.","example_zh":"種植蔬菜讓學生學會耐心。","original_meaning":"培養","original_example":"Crop cultivation requires patience.","original_example_zh":"作物栽培需要耐心。"},{"source_id":3249,"word":"curfew","meaning":"宵禁","example":"The campsite's curfew required everyone to return to the cabins before night.","example_zh":"營地的宵禁規定，要求大家夜晚前返回木屋。","original_meaning":"宵禁","original_example":"The city imposed a curfew at night.","original_example_zh":"該市實施夜間宵禁。"},{"source_id":3250,"word":"cybernetics","meaning":"控制論","example":"The cybernetics lesson used a thermostat to explain feedback.","example_zh":"控制論課程用恆溫器說明回饋作用。","original_meaning":"控制論","original_example":"Cybernetics studies control systems.","original_example_zh":"控制論研究控制系統。"},{"source_id":3251,"word":"cynicism","meaning":"犬儒主義；冷嘲的態度","example":"His cynicism softened when he saw the volunteers helping without reward.","example_zh":"看到志工不求回報地幫忙，他的冷嘲態度緩和了。","original_meaning":"犬儒主義","original_example":"His cynicism made him unpopular.","original_example_zh":"他的玩世不恭使他不得人心。"},{"source_id":3252,"word":"dashboard","meaning":"儀表板","example":"The driver checked the dashboard before starting the bus.","example_zh":"司機發動公車前先檢查儀表板。","original_meaning":"儀表板","original_example":"The dashboard displays key information.","original_example_zh":"儀表板顯示關鍵資訊。"},{"source_id":3253,"word":"deacon","meaning":"執事","example":"The deacon helped distribute food to families after the service.","example_zh":"禮拜後，執事幫忙把食物分送給家庭。","original_meaning":"執事","original_example":"The deacon assisted in the service.","original_example_zh":"執事協助了禮拜儀式。"},{"source_id":3254,"word":"decadence","meaning":"頹廢；奢靡","example":"The story contrasted the palace's decadence with the villagers' simple life.","example_zh":"故事對比宮殿的奢靡與村民的簡樸生活。","original_meaning":"頹廢","original_example":"The novel portrays moral decadence.","original_example_zh":"這部小說描繪了道德的墮落。"},{"source_id":3255,"word":"decentralize","meaning":"分散","example":"The library will decentralize its services by opening small branches.","example_zh":"圖書館將設立小型分館，分散提供服務。","original_meaning":"分散","original_example":"The company aims to decentralize operations.","original_example_zh":"該公司旨在將營運權下放。"},{"source_id":3256,"word":"deception","meaning":"欺騙","example":"The hidden mirror revealed the deception behind the magic trick.","example_zh":"隱藏鏡子揭露了魔術戲法背後的騙術。","original_meaning":"欺騙","original_example":"The scam involved deception.","original_example_zh":"這場詐騙涉及欺騙。"},{"source_id":3257,"word":"decimation","meaning":"毀滅","example":"The storm caused the decimation of the old orchard.","example_zh":"暴風雨讓老果園遭到嚴重破壞。","original_meaning":"毀滅","original_example":"The war caused massive decimation.","original_example_zh":"戰爭造成大規模的殲滅。"},{"source_id":3258,"word":"decomposition","meaning":"分解","example":"The students observed decomposition as fallen leaves slowly became compost.","example_zh":"學生觀察落葉慢慢變成堆肥的分解過程。","original_meaning":"分解","original_example":"Organic matter undergoes decomposition.","original_example_zh":"有機物會發生分解。"},{"source_id":3259,"word":"deflation","meaning":"通縮","example":"The class used market models to explore how deflation lowers general prices.","example_zh":"班上用市場模型探討通貨緊縮如何使整體物價下降。","original_meaning":"通縮","original_example":"The country faced economic deflation.","original_example_zh":"該國面臨經濟通縮。"},{"source_id":3260,"word":"deforestation","meaning":"森林砍伐","example":"The hillside showed the effects of deforestation after many trees were removed.","example_zh":"許多樹被砍除後，山坡顯現森林砍伐的影響。","original_meaning":"森林砍伐","original_example":"The documentary connects deforestation with the loss of animal habitats.","original_example_zh":"紀錄片說明森林砍伐與動物棲地消失之間的關聯。"},{"source_id":3261,"word":"deity","meaning":"神","example":"The ancient sculpture represented a deity associated with the sea.","example_zh":"這座古代雕像代表與海洋有關的神祇。","original_meaning":"神","original_example":"Ancient cultures worshipped many deities.","original_example_zh":"古代文化崇拜許多神祇。"},{"source_id":3262,"word":"deliberation","meaning":"審議","example":"After careful deliberation, the council chose the safer route.","example_zh":"仔細審議後，委員會選擇較安全的路線。","original_meaning":"審議","original_example":"The decision followed careful deliberation.","original_example_zh":"這項決定是在仔細斟酌後做出的。"},{"source_id":3263,"word":"delinquent","meaning":"犯罪少年","example":"The counselor helped the young delinquent plan a return to school.","example_zh":"輔導員幫助那位少年犯規劃重返校園。","original_meaning":"犯罪少年","original_example":"The delinquent was sent to a correctional facility.","original_example_zh":"該名罪犯被送往矯正機構。"},{"source_id":3264,"word":"delusion","meaning":"妄想","example":"It was a delusion to think the tiny paper boat could carry a person.","example_zh":"以為小紙船能載得動一個人，實在是妄想。","original_meaning":"妄想","original_example":"He suffered from a strange delusion.","original_example_zh":"他深受一種奇怪的妄想所苦。"},{"source_id":3265,"word":"demeanor","meaning":"態度","example":"The nurse's calm demeanor helped the nervous visitor relax.","example_zh":"護理師沉著的態度讓緊張的訪客放鬆下來。","original_meaning":"態度","original_example":"Her calm demeanor impressed everyone.","original_example_zh":"她沉著的舉止令眾人印象深刻。"},{"source_id":3266,"word":"demographics","meaning":"人口統計","example":"The students studied the town's demographics before planning community activities.","example_zh":"學生規劃社區活動前，先研究城鎮的人口統計。","original_meaning":"人口統計","original_example":"The report analyzed demographics.","original_example_zh":"該報告分析了人口統計數據。"},{"source_id":3267,"word":"demolish","meaning":"拆除","example":"The workers will demolish the unsafe shed before rebuilding it.","example_zh":"工人將拆除不安全的棚屋，再重新建造。","original_meaning":"拆除","original_example":"They plan to demolish the old building.","original_example_zh":"他們計劃拆除舊建築。"},{"source_id":3268,"word":"denomination","meaning":"教派","example":"The museum described the history of a small religious denomination.","example_zh":"博物館介紹一個小宗教教派的歷史。","original_meaning":"教派","original_example":"The church belongs to a specific denomination.","original_example_zh":"該教會隸屬於特定教派。"},{"source_id":3269,"word":"depiction","meaning":"描繪","example":"The painting offered a vivid depiction of life beside the river.","example_zh":"畫作生動描繪河邊生活。","original_meaning":"描繪","original_example":"The painting is a vivid depiction of life.","original_example_zh":"這幅畫生動地描繪了生活。"},{"source_id":3270,"word":"deployment","meaning":"部署","example":"The deployment of the rescue boats began as the river rose.","example_zh":"河水上漲時，救援船隻開始部署。","original_meaning":"部署","original_example":"The deployment of troops was rapid.","original_example_zh":"部隊的部署行動迅速。"},{"source_id":3271,"word":"depreciation","meaning":"折舊","example":"The shop owner allowed for depreciation when valuing the old machine.","example_zh":"店主估算舊機器價值時，把折舊納入考量。","original_meaning":"折舊","original_example":"The asset lost value due to depreciation.","original_example_zh":"該資產因折舊而貶值。"},{"source_id":3272,"word":"deprivation","meaning":"匱乏","example":"The volunteers responded to the families' deprivation of basic supplies.","example_zh":"志工協助缺乏基本物資的家庭。","original_meaning":"匱乏","original_example":"Many suffered from food deprivation.","original_example_zh":"許多人飽受食物匱乏之苦。"},{"source_id":3273,"word":"derail","meaning":"脫軌；打亂","example":"A missing part could derail our plan to finish the model train.","example_zh":"缺少一個零件可能打亂我們完成模型火車的計畫。","original_meaning":"脫軌","original_example":"The train might derail at high speed.","original_example_zh":"火車在高速行駛時可能會脫軌。"},{"source_id":3274,"word":"deregulation","meaning":"解除管制","example":"The class discussed deregulation and its effects on local bus companies.","example_zh":"班上討論解除管制對當地公車公司的影響。","original_meaning":"解除管制","original_example":"Deregulation can boost competition.","original_example_zh":"解除管制可以促進競爭。"},{"source_id":3275,"word":"descendant","meaning":"後裔","example":"The artist's descendant donated her old sketches to the museum.","example_zh":"藝術家的後裔把她留下的老素描捐給博物館。","original_meaning":"後裔","original_example":"He is a descendant of a royal family.","original_example_zh":"他是王室的後裔。"},{"source_id":3276,"word":"desertification","meaning":"沙漠化","example":"The village planted trees to slow desertification around its fields.","example_zh":"村民種樹，減緩農田周圍的沙漠化。","original_meaning":"沙漠化","original_example":"Desertification threatens agriculture.","original_example_zh":"沙漠化威脅著農業。"},{"source_id":3277,"word":"designation","meaning":"指定","example":"The site's designation as a reserve helped protect its wildlife.","example_zh":"這個地方被指定為保護區，有助保護野生動物。","original_meaning":"指定","original_example":"She received the official designation.","original_example_zh":"她獲得了正式任命。"},{"source_id":3278,"word":"desolate","meaning":"荒涼的","example":"The abandoned station looked desolate in the winter rain.","example_zh":"冬雨中的廢棄車站顯得荒涼。","original_meaning":"荒涼的","original_example":"The desert looked desolate and empty.","original_example_zh":"沙漠看起來荒涼而空曠。"},{"source_id":3279,"word":"detachment","meaning":"超然","example":"The judge listened with detachment before examining the evidence.","example_zh":"法官以超然客觀的態度聆聽，再檢視證據。","original_meaning":"超然","original_example":"She maintained emotional detachment.","original_example_zh":"她保持著情感上的疏離。"},{"source_id":3280,"word":"detention","meaning":"拘留；留校","example":"The student spent detention quietly finishing the missed assignment.","example_zh":"那位學生在留校時安靜完成缺交作業。","original_meaning":"拘留","original_example":"He was held in detention overnight.","original_example_zh":"他被拘留了一整夜。"},{"source_id":3281,"word":"deterrent","meaning":"嚇阻；阻止因素","example":"The sturdy fence acted as a deterrent to deer entering the garden.","example_zh":"堅固柵欄阻止鹿闖進菜園。","original_meaning":"嚇阻","original_example":"Strict laws act as a deterrent.","original_example_zh":"嚴格的法律具有威懾作用。"},{"source_id":3282,"word":"devastation","meaning":"破壞","example":"The volunteers helped clear the devastation left by the storm.","example_zh":"志工幫忙清理風暴留下的破壞。","original_meaning":"破壞","original_example":"The hurricane caused widespread devastation.","original_example_zh":"颶風造成廣泛的破壞。"},{"source_id":3283,"word":"deviation","meaning":"偏差","example":"A small deviation from the plan made the model bridge lean.","example_zh":"與設計的一點偏差，讓模型橋傾斜了。","original_meaning":"偏差","original_example":"There was a slight deviation from the plan.","original_example_zh":"與計畫略有偏差。"},{"source_id":3284,"word":"diagnosis","meaning":"診斷","example":"The doctor explained the diagnosis to the patient in clear language.","example_zh":"醫師用清楚語言向病人說明診斷。","original_meaning":"診斷","original_example":"The doctor made a diagnosis quickly.","original_example_zh":"醫生迅速做出診斷。"},{"source_id":3285,"word":"dictatorship","meaning":"獨裁","example":"The history lesson explained how a dictatorship concentrates power in one ruler.","example_zh":"歷史課說明獨裁政體如何把權力集中於一位統治者。","original_meaning":"獨裁","original_example":"The country was ruled by a dictatorship.","original_example_zh":"該國由獨裁政權統治。"},{"source_id":3286,"word":"diffusion","meaning":"擴散","example":"A drop of dye showed diffusion as its color spread through the water.","example_zh":"一滴染料的顏色在水中散開，展現擴散現象。","original_meaning":"擴散","original_example":"Gas diffusion occurs naturally.","original_example_zh":"氣體擴散是自然現象。"},{"source_id":3287,"word":"digestion","meaning":"消化","example":"The classroom model showed the path food takes during digestion.","example_zh":"教室模型展示食物在消化過程中經過的路徑。","original_meaning":"消化","original_example":"Digestion begins in the stomach.","original_example_zh":"消化始於胃部。"},{"source_id":3288,"word":"dilute","meaning":"稀釋","example":"We added water to dilute the blue paint.","example_zh":"我們加水稀釋藍色顏料。","original_meaning":"稀釋","original_example":"Dilute the solution with water.","original_example_zh":"用水稀釋溶液。"},{"source_id":3289,"word":"diplomacy","meaning":"外交","example":"The museum exhibit showed how diplomacy helped settle the border dispute.","example_zh":"博物館展覽呈現外交如何幫助解決邊界爭議。","original_meaning":"外交","original_example":"Diplomacy avoids unnecessary conflict.","original_example_zh":"外交能避免不必要的衝突。"},{"source_id":3290,"word":"directive","meaning":"指令","example":"The safety directive required everyone to keep the doorway clear.","example_zh":"安全指令要求每個人保持門口暢通。","original_meaning":"指令","original_example":"Follow the directive carefully.","original_example_zh":"請仔細遵循指示。"},{"source_id":3291,"word":"disarmament","meaning":"裁軍","example":"The history class discussed disarmament as a way to reduce weapons.","example_zh":"歷史課討論透過裁軍減少武器。","original_meaning":"裁軍","original_example":"The treaty focused on disarmament.","original_example_zh":"該條約著重於裁軍。"},{"source_id":3292,"word":"disclaimer","meaning":"免責聲明","example":"The guidebook included a disclaimer about possible changes to the walking routes.","example_zh":"導覽手冊附上關於步道路線可能變更的免責聲明。","original_meaning":"免責聲明","original_example":"Please read the disclaimer before using this service.","original_example_zh":"使用本服務前請閱讀免責聲明。"},{"source_id":3293,"word":"discord","meaning":"不和","example":"The shared task helped resolve discord between the two clubs.","example_zh":"共同任務有助化解兩個社團的不和。","original_meaning":"不和","original_example":"The argument created discord among the team members.","original_example_zh":"這場爭論在團隊成員間引發了不和。"},{"source_id":3294,"word":"discretion","meaning":"審慎","example":"The guide used discretion when deciding whether the trail was safe.","example_zh":"嚮導審慎判斷步道是否安全。","original_meaning":"審慎","original_example":"Use your discretion when making decisions.","original_example_zh":"決策時請自行斟酌。"},{"source_id":3295,"word":"disintegration","meaning":"瓦解","example":"The old paper showed signs of disintegration along its edges.","example_zh":"舊紙張邊緣顯現逐漸碎裂的跡象。","original_meaning":"瓦解","original_example":"The empire collapsed due to internal disintegration.","original_example_zh":"帝國因內部瓦解而崩潰。"},{"source_id":3296,"word":"dismissal","meaning":"解僱","example":"The employee received notice of dismissal when the factory closed.","example_zh":"工廠關閉時，員工收到解僱通知。","original_meaning":"解僱","original_example":"His dismissal came as a shock to everyone.","original_example_zh":"他的解僱令所有人感到震驚。"},{"source_id":3297,"word":"displacement","meaning":"流離","example":"The flood caused the displacement of many families from their homes.","example_zh":"洪水使許多家庭被迫離家流離。","original_meaning":"流離","original_example":"War often leads to the displacement of civilians.","original_example_zh":"戰爭往往導致平民流離失所。"},{"source_id":3298,"word":"disposition","meaning":"性情","example":"Her cheerful disposition made new classmates feel welcome.","example_zh":"她開朗的性情讓新同學感到受歡迎。","original_meaning":"性情","original_example":"She has a calm and friendly disposition.","original_example_zh":"她性情沉穩友善。"},{"source_id":3299,"word":"dissemination","meaning":"散布","example":"The library helped with the dissemination of information about the festival.","example_zh":"圖書館幫忙傳播節慶資訊。","original_meaning":"散布","original_example":"The dissemination of information is important.","original_example_zh":"資訊的傳播至關重要。"},{"source_id":3300,"word":"dissolution","meaning":"解散","example":"The club's dissolution meant its tools had to be shared with other groups.","example_zh":"社團解散後，工具必須分給其他小組使用。","original_meaning":"解散","original_example":"The dissolution of the group was inevitable.","original_example_zh":"該團體的解散是不可避免的。"},{"source_id":3301,"word":"distortion","meaning":"扭曲","example":"The curved mirror caused a funny distortion of our reflections.","example_zh":"彎曲鏡面讓我們的倒影出現有趣的扭曲。","original_meaning":"扭曲","original_example":"The image suffered from distortion.","original_example_zh":"這張圖片因變形而受損。"},{"source_id":3302,"word":"diversion","meaning":"改道","example":"A road diversion led the school bus around the damaged bridge.","example_zh":"道路改道讓校車繞過受損橋梁。","original_meaning":"改道","original_example":"We had to take a diversion due to road work.","original_example_zh":"由於道路施工，我們不得不繞道而行。"},{"source_id":3303,"word":"dividend","meaning":"股息","example":"The company paid a dividend to its shareholders after a profitable year.","example_zh":"公司在獲利的一年後，向股東發放股息。","original_meaning":"股息","original_example":"Shareholders received a dividend this year.","original_example_zh":"股東們今年收到了股息。"},{"source_id":3304,"word":"domesticate","meaning":"馴化","example":"The exhibit explained how people began to domesticate wild plants.","example_zh":"展覽說明人類如何開始馴化野生植物。","original_meaning":"馴化","original_example":"Humans began to domesticate animals long ago.","original_example_zh":"人類早在很久以前就開始馴養動物。"},{"source_id":3305,"word":"dominance","meaning":"主導","example":"The tall tree's dominance kept the smaller plants in deep shade.","example_zh":"高大樹木的主導地位，讓小植物長期處於深蔭。","original_meaning":"主導","original_example":"The company achieved market dominance.","original_example_zh":"該公司取得了市場主導地位。"},{"source_id":3306,"word":"dormant","meaning":"休眠的","example":"The seeds remained dormant until spring brought warmth and rain.","example_zh":"種子一直休眠，直到春天帶來溫暖與雨水。","original_meaning":"休眠的","original_example":"The volcano remained dormant for centuries.","original_example_zh":"這座火山沉寂了數世紀。"},{"source_id":3307,"word":"dosage","meaning":"劑量","example":"The pharmacist carefully checked the dosage on the prescription.","example_zh":"藥師仔細核對處方上的劑量。","original_meaning":"劑量","original_example":"Follow the prescribed dosage carefully.","original_example_zh":"請嚴格遵循規定劑量。"},{"source_id":3308,"word":"downturn","meaning":"衰退","example":"The economic downturn left several shops on the street empty.","example_zh":"經濟衰退讓街上好幾間店面空置。","original_meaning":"衰退","original_example":"The economy is facing a downturn.","original_example_zh":"經濟正面臨衰退。"},{"source_id":3309,"word":"draftsman","meaning":"製圖員","example":"The draftsman prepared precise plans for the new library.","example_zh":"製圖員為新圖書館繪製精確設計圖。","original_meaning":"製圖員","original_example":"The draftsman created a detailed plan.","original_example_zh":"製圖員繪製了一份詳細的藍圖。"},{"source_id":3310,"word":"drainage","meaning":"排水","example":"The new drainage channels kept rainwater off the school path.","example_zh":"新的排水溝讓雨水不再積在校園步道上。","original_meaning":"排水","original_example":"Proper drainage prevents flooding.","original_example_zh":"完善的排水系統可防止淹水。"},{"source_id":3311,"word":"drastic","meaning":"激烈的","example":"The drought forced a drastic reduction in water use.","example_zh":"乾旱迫使人們大幅減少用水。","original_meaning":"激烈的","original_example":"The situation requires drastic measures.","original_example_zh":"情勢需要採取激進措施。"},{"source_id":3312,"word":"dubious","meaning":"可疑的","example":"The expert looked dubious when shown the unusually shiny old coin.","example_zh":"看到異常閃亮的古幣時，專家露出懷疑神情。","original_meaning":"可疑的","original_example":"His explanation sounded dubious.","original_example_zh":"他的解釋聽起來很可疑。"},{"source_id":3313,"word":"dysfunction","meaning":"功能障礙","example":"A loose sensor caused dysfunction in the model robot's steering system.","example_zh":"鬆動的感測器使模型機器人的轉向系統失常。","original_meaning":"功能障礙","original_example":"The patient was diagnosed with a dysfunction.","original_example_zh":"該患者被診斷出功能障礙。"},{"source_id":3314,"word":"eagerness","meaning":"渴望","example":"The students' eagerness to learn was clear from their many questions.","example_zh":"學生踴躍提問，充分展現求知的渴望。","original_meaning":"渴望","original_example":"Her eagerness to learn impressed the teacher.","original_example_zh":"她求知若渴的態度給老師留下了深刻印象。"},{"source_id":3315,"word":"edict","meaning":"法令","example":"The royal edict required the ancient woodland to be protected.","example_zh":"王室法令要求保護古老林地。","original_meaning":"法令","original_example":"The king issued a royal edict.","original_example_zh":"國王頒布了一道詔書。"},{"source_id":3316,"word":"efficacy","meaning":"功效","example":"The students tested the efficacy of two water filters.","example_zh":"學生測試兩種濾水器的功效。","original_meaning":"功效","original_example":"The drug has proven efficacy.","original_example_zh":"該藥物已證實有效。"},{"source_id":3317,"word":"egalitarian","meaning":"平等主義的","example":"The club took an egalitarian approach and gave every member a voice.","example_zh":"社團採取平等的方式，讓每位成員都有發言機會。","original_meaning":"平等主義的","original_example":"They believe in an egalitarian society.","original_example_zh":"他們相信平等主義社會。"},{"source_id":3318,"word":"elaboration","meaning":"闡述","example":"The teacher's elaboration helped us understand the simple sketch.","example_zh":"老師進一步闡述，幫助我們理解簡單草圖。","original_meaning":"闡述","original_example":"The report needs further elaboration.","original_example_zh":"這份報告需要進一步闡述。"},{"source_id":3319,"word":"electromagnetic","meaning":"電磁的","example":"The class used an electromagnetic coil to lift small metal objects.","example_zh":"班上使用電磁線圈提起小金屬物件。","original_meaning":"電磁的","original_example":"Electromagnetic waves travel at the speed of light.","original_example_zh":"電磁波以光速傳播。"},{"source_id":3320,"word":"elevation","meaning":"海拔","example":"The higher elevation made the air feel cooler on the mountain trail.","example_zh":"較高的海拔讓山徑上的空氣感覺更涼。","original_meaning":"海拔","original_example":"The mountain has a high elevation.","original_example_zh":"這座山海拔很高。"},{"source_id":3321,"word":"eligibility","meaning":"資格","example":"The teacher checked each student's eligibility for the science competition.","example_zh":"老師確認每位學生是否符合科學競賽資格。","original_meaning":"資格","original_example":"Check your eligibility before applying.","original_example_zh":"申請前請確認您的資格。"},{"source_id":3322,"word":"elite","meaning":"精英","example":"The festival invited an elite of talented young musicians to perform.","example_zh":"音樂節邀請一群出色的年輕音樂家演出。","original_meaning":"精英","original_example":"Only the elite were invited.","original_example_zh":"僅邀請了精英階層。"},{"source_id":3323,"word":"eloquence","meaning":"口才","example":"Her eloquence made the complex story easy to follow.","example_zh":"她流暢的口才讓複雜故事變得容易理解。","original_meaning":"口才","original_example":"Her eloquence moved the audience.","original_example_zh":"她的雄辯打動了觀眾。"},{"source_id":3324,"word":"emancipation","meaning":"解放","example":"The exhibit explored the struggle for emancipation from slavery.","example_zh":"展覽探討擺脫奴隸制度、爭取解放的歷程。","original_meaning":"解放","original_example":"The law marked the emancipation of slaves.","original_example_zh":"該法律標誌著奴隸的解放。"},{"source_id":3325,"word":"embargo","meaning":"禁運","example":"The embargo stopped certain goods from leaving the harbor.","example_zh":"禁運令阻止某些貨物離開港口。","original_meaning":"禁運","original_example":"The country imposed an embargo.","original_example_zh":"該國實施了禁運。"},{"source_id":3326,"word":"embodiment","meaning":"體現","example":"The carefully restored garden was an embodiment of the community's care.","example_zh":"細心修復的花園，體現社區居民的關懷。","original_meaning":"體現","original_example":"She is the embodiment of kindness.","original_example_zh":"她是仁慈的化身。"},{"source_id":3327,"word":"emigrant","meaning":"移民","example":"The emigrant packed family photographs before leaving for a new country.","example_zh":"那位移出國門的人在前往新國家前，打包家人照片。","original_meaning":"移民","original_example":"The emigrant settled in a new country.","original_example_zh":"移民定居於新國家。"},{"source_id":3328,"word":"eminent","meaning":"傑出的","example":"An eminent astronomer visited our school to discuss the stars.","example_zh":"一位傑出的天文學家來校談論星空。","original_meaning":"傑出的","original_example":"He is an eminent scientist.","original_example_zh":"他是一位傑出的科學家。"},{"source_id":3329,"word":"empower","meaning":"賦權","example":"Learning to repair bicycles can empower students to solve practical problems.","example_zh":"學會修理腳踏車，能讓學生更有能力解決實際問題。","original_meaning":"賦權","original_example":"The program aims to empower women.","original_example_zh":"該計畫旨在賦權女性。"},{"source_id":3330,"word":"enclave","meaning":"飛地","example":"The map showed an enclave surrounded by another country's territory.","example_zh":"地圖顯示一塊被另一國領土包圍的飛地。","original_meaning":"飛地","original_example":"The enclave is surrounded by another country.","original_example_zh":"該飛地被另一國包圍。"},{"source_id":3331,"word":"encryption","meaning":"加密","example":"The lesson showed how encryption helps protect a message from unwanted readers.","example_zh":"課程展示加密如何保護訊息，避免被未授權的人讀取。","original_meaning":"加密","original_example":"Encryption protects sensitive data.","original_example_zh":"加密技術保護敏感資料。"},{"source_id":3332,"word":"endorsement","meaning":"背書；支持推薦","example":"The coach's endorsement encouraged more students to join the safety program.","example_zh":"教練的支持推薦，鼓勵更多學生參加安全課程。","original_meaning":"背書","original_example":"The product gained celebrity endorsement.","original_example_zh":"該產品獲得名人代言。"},{"source_id":3333,"word":"endowment","meaning":"捐贈基金","example":"The alumnus created an endowment to support the library for many years.","example_zh":"校友設立捐贈基金，長期支持圖書館。","original_meaning":"捐贈基金","original_example":"The university received a large endowment.","original_example_zh":"該大學獲得一筆龐大的捐贈。"},{"source_id":3334,"word":"enigmatic","meaning":"神秘的","example":"The old key had an enigmatic symbol that no one could explain.","example_zh":"那把舊鑰匙上有個沒人能解釋的神祕符號。","original_meaning":"神秘的","original_example":"The story has an enigmatic ending.","original_example_zh":"這個故事有個撲朔迷離的結局。"},{"source_id":3335,"word":"enlightenment","meaning":"啟蒙","example":"The museum visit brought a sense of enlightenment about the natural world.","example_zh":"參訪博物館帶來對自然世界更深入了解的啟發。","original_meaning":"啟蒙","original_example":"The Enlightenment influenced modern thought.","original_example_zh":"啟蒙運動影響了現代思想。"},{"source_id":3336,"word":"ensemble","meaning":"合奏","example":"The small ensemble rehearsed a gentle piece for the school concert.","example_zh":"小型合奏團為學校音樂會排練一首柔和樂曲。","original_meaning":"合奏","original_example":"The band performed as an ensemble.","original_example_zh":"樂團以合奏形式演出。"},{"source_id":3337,"word":"entitlement","meaning":"權利","example":"The pass confirmed her entitlement to use the library's study rooms.","example_zh":"通行證確認她有權使用圖書館自習室。","original_meaning":"權利","original_example":"Citizens are entitled to basic rights.","original_example_zh":"公民享有基本權利。"},{"source_id":3338,"word":"entropy","meaning":"熵","example":"The entropy model showed particles spreading throughout a container.","example_zh":"熵的模型展示粒子散布到整個容器的情形。","original_meaning":"熵","original_example":"Entropy increases in a closed system.","original_example_zh":"在封閉系統中，熵會增加。"},{"source_id":3339,"word":"envoy","meaning":"特使","example":"The envoy delivered a message of peace to the neighboring kingdom.","example_zh":"特使把和平訊息送到鄰近王國。","original_meaning":"特使","original_example":"The country sent an envoy to negotiate peace.","original_example_zh":"該國派遣特使進行和平談判。"},{"source_id":3340,"word":"epitome","meaning":"典範","example":"The carefully balanced bridge was the epitome of thoughtful design.","example_zh":"這座平衡精巧的橋，是周到設計的典範。","original_meaning":"典範","original_example":"She is the epitome of elegance.","original_example_zh":"她是優雅的化身。"},{"source_id":3341,"word":"equilibrium","meaning":"平衡","example":"The balanced scale remained in equilibrium with equal weights on both sides.","example_zh":"天平兩端重量相等，因此維持平衡。","original_meaning":"平衡","original_example":"The market reached an equilibrium.","original_example_zh":"市場達到了平衡狀態。"},{"source_id":3342,"word":"eradicate","meaning":"根除","example":"The gardeners worked together to eradicate the invasive weeds.","example_zh":"園丁合作根除入侵雜草。","original_meaning":"根除","original_example":"The government aims to eradicate poverty.","original_example_zh":"政府致力於消除貧窮。"},{"source_id":3343,"word":"espionage","meaning":"間諜","example":"The history exhibit explained how espionage was used to gather secret information.","example_zh":"歷史展覽說明間諜活動如何被用來蒐集機密資訊。","original_meaning":"間諜","original_example":"The novel involves espionage during wartime.","original_example_zh":"這部小說涉及戰時間諜活動。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-critique-01-v1","level":"senior","word":"critique","sort_order":1,"sense":"評論","alt_zh":"老師耐心指出高中生模型橋可以改進的支架，同學專心聆聽。","example":"The teacher's thoughtful critique helped us improve the model bridge.","example_zh":"老師周到的評論幫助我們改進模型橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/critique-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-crossroads-01-v1","level":"senior","word":"crossroads","sort_order":1,"sense":"十字路口","alt_zh":"高中健行隊在安全人行區集合，旁邊兩條村道呈十字交會。","example":"We met at the crossroads where the two village roads intersect.","example_zh":"我們在兩條村道交會的十字路口碰面。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/crossroads-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-crucible-01-v1","level":"senior","word":"crucible","sort_order":1,"sense":"坩堝","alt_zh":"成年金屬工匠穿完整防護裝備，在安全工坊用長柄工具處理固定好的小坩堝。","example":"The metalworker used a crucible to hold the heated metal.","example_zh":"金屬工匠用坩堝盛裝加熱的金屬。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/crucible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-crusade-01-v1","level":"senior","word":"crusade","sort_order":1,"sense":"運動","alt_zh":"高中志工在海灘集合，準備清理塑膠垃圾並分發可重複使用用品。","example":"The students began a crusade against plastic litter on the beach.","example_zh":"學生發起抵制海灘塑膠垃圾的運動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/crusade-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cultivation-01-v1","level":"senior","word":"cultivation","sort_order":1,"sense":"培養；栽培","alt_zh":"高中生在校園菜圃細心鬆土、澆水與照顧漸漸長大的蔬菜。","example":"The cultivation of vegetables taught the students patience.","example_zh":"種植蔬菜讓學生學會耐心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cultivation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-curfew-01-v1","level":"senior","word":"curfew","sort_order":1,"sense":"宵禁","alt_zh":"暮色營地中，老師招呼高中生回到明亮安全的小木屋。","example":"The campsite's curfew required everyone to return to the cabins before night.","example_zh":"營地的宵禁規定，要求大家夜晚前返回木屋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/curfew-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cybernetics-01-v1","level":"senior","word":"cybernetics","sort_order":1,"sense":"控制論","alt_zh":"老師在科學教室展示透明恆溫器模型與風扇回饋裝置，高中生觀察。","example":"The cybernetics lesson used a thermostat to explain feedback.","example_zh":"控制論課程用恆溫器說明回饋作用。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cybernetics-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cynicism-01-v1","level":"senior","word":"cynicism","sort_order":1,"sense":"犬儒主義；冷嘲的態度","alt_zh":"起初抱臂懷疑的高中生，看見同學真誠幫長者搬物資後放鬆神情。","example":"His cynicism softened when he saw the volunteers helping without reward.","example_zh":"看到志工不求回報地幫忙，他的冷嘲態度緩和了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cynicism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dashboard-01-v1","level":"senior","word":"dashboard","sort_order":1,"sense":"儀表板","alt_zh":"成年公車司機坐在駕駛座，仔細查看方向盤後方儀表與指示燈。","example":"The driver checked the dashboard before starting the bus.","example_zh":"司機發動公車前先檢查儀表板。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dashboard-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deacon-01-v1","level":"senior","word":"deacon","sort_order":1,"sense":"執事","alt_zh":"成年教會執事在社區教堂側廳，友善把食物箱交給有需要的家庭。","example":"The deacon helped distribute food to families after the service.","example_zh":"禮拜後，執事幫忙把食物分送給家庭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deacon-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decadence-01-v1","level":"senior","word":"decadence","sort_order":1,"sense":"頹廢；奢靡","alt_zh":"虛構歷史宮殿裡，奢華餐桌留下大量沒吃完食物，窗外可見簡樸村舍。","example":"The story contrasted the palace's decadence with the villagers' simple life.","example_zh":"故事對比宮殿的奢靡與村民的簡樸生活。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decadence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decentralize-01-v1","level":"senior","word":"decentralize","sort_order":1,"sense":"分散","alt_zh":"城鎮地景模型中，中央大圖書館與分布各區的小分館相連，高中生觀察。","example":"The library will decentralize its services by opening small branches.","example_zh":"圖書館將設立小型分館，分散提供服務。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decentralize-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deception-01-v1","level":"senior","word":"deception","sort_order":1,"sense":"欺騙","alt_zh":"成年魔術師向高中生展示道具箱裡的隱藏鏡子，解說單純舞台幻術。","example":"The hidden mirror revealed the deception behind the magic trick.","example_zh":"隱藏鏡子揭露了魔術戲法背後的騙術。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deception-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decimation-01-v1","level":"senior","word":"decimation","sort_order":1,"sense":"毀滅","alt_zh":"風暴過後，多數果樹倒下或折枝，農人從安全小徑查看，無傷者。","example":"The storm caused the decimation of the old orchard.","example_zh":"暴風雨讓老果園遭到嚴重破壞。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decimation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-decomposition-01-v1","level":"senior","word":"decomposition","sort_order":1,"sense":"分解","alt_zh":"老師與高中生查看透明堆肥箱內由落葉逐漸變成深色腐植質的層次。","example":"The students observed decomposition as fallen leaves slowly became compost.","example_zh":"學生觀察落葉慢慢變成堆肥的分解過程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/decomposition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deflation-01-v1","level":"senior","word":"deflation","sort_order":1,"sense":"通縮","alt_zh":"高中生比較兩個市場模型，用較少硬幣能換到相同種類與數量商品，無標價文字。","example":"The class used market models to explore how deflation lowers general prices.","example_zh":"班上用市場模型探討通貨緊縮如何使整體物價下降。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deflation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deforestation-01-v1","level":"senior","word":"deforestation","sort_order":1,"sense":"森林砍伐","alt_zh":"高中生從安全觀景點看山坡一側的大片樹樁與裸露土壤。","example":"The hillside showed the effects of deforestation after many trees were removed.","example_zh":"許多樹被砍除後，山坡顯現森林砍伐的影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deforestation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deity-01-v1","level":"senior","word":"deity","sort_order":1,"sense":"神","alt_zh":"高中生在博物館欣賞古老海洋神祇石雕，雕像持海浪形裝飾。","example":"The ancient sculpture represented a deity associated with the sea.","example_zh":"這座古代雕像代表與海洋有關的神祇。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deliberation-01-v1","level":"senior","word":"deliberation","sort_order":1,"sense":"審議","alt_zh":"學生會與老師圍桌討論兩條步道路線模型，最後指向平緩安全的道路。","example":"After careful deliberation, the council chose the safer route.","example_zh":"仔細審議後，委員會選擇較安全的路線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deliberation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-delinquent-01-v1","level":"senior","word":"delinquent","sort_order":1,"sense":"犯罪少年","alt_zh":"輔導員在溫暖辦公室陪年輕學生規劃上學，桌上有課本與書包，無拘束器具。","example":"The counselor helped the young delinquent plan a return to school.","example_zh":"輔導員幫助那位少年犯規劃重返校園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/delinquent-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-delusion-01-v1","level":"senior","word":"delusion","sort_order":1,"sense":"妄想","alt_zh":"高中生在科學教室看著手掌大小紙船漂在水盆，老師用人物模型說明尺度限制。","example":"It was a delusion to think the tiny paper boat could carry a person.","example_zh":"以為小紙船能載得動一個人，實在是妄想。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/delusion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-demeanor-01-v1","level":"senior","word":"demeanor","sort_order":1,"sense":"態度","alt_zh":"溫和的成年護理師在接待處耐心交談，緊張的訪客逐漸微笑。","example":"The nurse's calm demeanor helped the nervous visitor relax.","example_zh":"護理師沉著的態度讓緊張的訪客放鬆下來。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demeanor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-demographics-01-v1","level":"senior","word":"demographics","sort_order":1,"sense":"人口統計","alt_zh":"高中生在社區中心觀察無字人口圖表，以不同年齡人物圖示比較居民組成。","example":"The students studied the town's demographics before planning community activities.","example_zh":"學生規劃社區活動前，先研究城鎮的人口統計。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demographics-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-demolish-01-v1","level":"senior","word":"demolish","sort_order":1,"sense":"拆除","alt_zh":"成年工人在封鎖安全區內有序拆除破舊空棚屋，學生從遠處看，無危險細節。","example":"The workers will demolish the unsafe shed before rebuilding it.","example_zh":"工人將拆除不安全的棚屋，再重新建造。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demolish-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-denomination-01-v1","level":"senior","word":"denomination","sort_order":1,"sense":"教派","alt_zh":"高中生在宗教文化博物館聽導覽，展示櫃有不同歷史教堂模型與文物。","example":"The museum described the history of a small religious denomination.","example_zh":"博物館介紹一個小宗教教派的歷史。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/denomination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-depiction-01-v1","level":"senior","word":"depiction","sort_order":1,"sense":"描繪","alt_zh":"高中生欣賞畫廊裡描繪河岸居民洗菜、划船與聊天的繪畫。","example":"The painting offered a vivid depiction of life beside the river.","example_zh":"畫作生動描繪河邊生活。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/depiction-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deployment-01-v1","level":"senior","word":"deployment","sort_order":1,"sense":"部署","alt_zh":"成年救援隊在安全碼頭依序準備救援小艇與救生衣，無傷者。","example":"The deployment of the rescue boats began as the river rose.","example_zh":"河水上漲時，救援船隻開始部署。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deployment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-depreciation-01-v1","level":"senior","word":"depreciation","sort_order":1,"sense":"折舊","alt_zh":"成年店主比較磨損舊縫紉機與嶄新機器，桌上用硬幣堆表示不同價值，無數字。","example":"The shop owner allowed for depreciation when valuing the old machine.","example_zh":"店主估算舊機器價值時，把折舊納入考量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/depreciation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deprivation-01-v1","level":"senior","word":"deprivation","sort_order":1,"sense":"匱乏","alt_zh":"志工把食物、毛毯與乾淨飲水交給物資不足的家庭，場景有尊嚴。","example":"The volunteers responded to the families' deprivation of basic supplies.","example_zh":"志工協助缺乏基本物資的家庭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deprivation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-derail-01-v1","level":"senior","word":"derail","sort_order":1,"sense":"脫軌；打亂","alt_zh":"高中生發現模型火車少了關鍵車軸零件，停下組裝並討論解決方法。","example":"A missing part could derail our plan to finish the model train.","example_zh":"缺少一個零件可能打亂我們完成模型火車的計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/derail-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deregulation-01-v1","level":"senior","word":"deregulation","sort_order":1,"sense":"解除管制","alt_zh":"老師用多家公司公車模型與無字規則卡，向高中生解說交通制度變化。","example":"The class discussed deregulation and its effects on local bus companies.","example_zh":"班上討論解除管制對當地公車公司的影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deregulation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-descendant-01-v1","level":"senior","word":"descendant","sort_order":1,"sense":"後裔","alt_zh":"成年後裔把祖先的素描本交給博物館員，旁邊有藝術家的老照片。","example":"The artist's descendant donated her old sketches to the museum.","example_zh":"藝術家的後裔把她留下的老素描捐給博物館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/descendant-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-desertification-01-v1","level":"senior","word":"desertification","sort_order":1,"sense":"沙漠化","alt_zh":"村民與高中志工在沙地與農田交界種植防風樹苗。","example":"The village planted trees to slow desertification around its fields.","example_zh":"村民種樹，減緩農田周圍的沙漠化。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/desertification-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-designation-01-v1","level":"senior","word":"designation","sort_order":1,"sense":"指定","alt_zh":"保育員在濕地入口設好護欄與無字動物圖示，遊客沿指定步道行走。","example":"The site's designation as a reserve helped protect its wildlife.","example_zh":"這個地方被指定為保護區，有助保護野生動物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/designation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-desolate-01-v1","level":"senior","word":"desolate","sort_order":1,"sense":"荒涼的","alt_zh":"空無一人的廢棄小車站在細雨與枯草間顯得冷清荒涼。","example":"The abandoned station looked desolate in the winter rain.","example_zh":"冬雨中的廢棄車站顯得荒涼。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/desolate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-detachment-01-v1","level":"senior","word":"detachment","sort_order":1,"sense":"超然","alt_zh":"成年法官在莊嚴法庭保持平靜中立，專注聆聽雙方並查看文件。","example":"The judge listened with detachment before examining the evidence.","example_zh":"法官以超然客觀的態度聆聽，再檢視證據。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/detachment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-detention-01-v1","level":"senior","word":"detention","sort_order":1,"sense":"拘留；留校","alt_zh":"高中生在放學後教室裡安靜補作業，老師在旁桌工作，無懲罰或束縛。","example":"The student spent detention quietly finishing the missed assignment.","example_zh":"那位學生在留校時安靜完成缺交作業。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/detention-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deterrent-01-v1","level":"senior","word":"deterrent","sort_order":1,"sense":"嚇阻；阻止因素","alt_zh":"鹿停在完整柵欄外，裡面的蔬菜園受到保護。","example":"The sturdy fence acted as a deterrent to deer entering the garden.","example_zh":"堅固柵欄阻止鹿闖進菜園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deterrent-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-devastation-01-v1","level":"senior","word":"devastation","sort_order":1,"sense":"破壞","alt_zh":"風暴過後，志工在安全村道收拾倒枝與破損屋瓦，無傷者。","example":"The volunteers helped clear the devastation left by the storm.","example_zh":"志工幫忙清理風暴留下的破壞。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/devastation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-deviation-01-v1","level":"senior","word":"deviation","sort_order":1,"sense":"偏差","alt_zh":"高中生比較精確圖紙與略歪的模型橋，老師指出支架位置差異。","example":"A small deviation from the plan made the model bridge lean.","example_zh":"與設計的一點偏差，讓模型橋傾斜了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deviation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diagnosis-01-v1","level":"senior","word":"diagnosis","sort_order":1,"sense":"診斷","alt_zh":"成年醫師在平靜診間指著無字檢查圖表，耐心向成年病人解釋。","example":"The doctor explained the diagnosis to the patient in clear language.","example_zh":"醫師用清楚語言向病人說明診斷。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diagnosis-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dictatorship-01-v1","level":"senior","word":"dictatorship","sort_order":1,"sense":"獨裁","alt_zh":"老師以虛構政治制度模型向高中生客觀解說，一位成年統治者掌管中央決策，無標語。","example":"The history lesson explained how a dictatorship concentrates power in one ruler.","example_zh":"歷史課說明獨裁政體如何把權力集中於一位統治者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dictatorship-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diffusion-01-v1","level":"senior","word":"diffusion","sort_order":1,"sense":"擴散","alt_zh":"高中生在老師旁觀察透明水杯中少量藍色食用色素緩緩擴散。","example":"A drop of dye showed diffusion as its color spread through the water.","example_zh":"一滴染料的顏色在水中散開，展現擴散現象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diffusion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-digestion-01-v1","level":"senior","word":"digestion","sort_order":1,"sense":"消化","alt_zh":"老師指著透明教學人體模型的胃與腸道，高中生認真觀察。","example":"The classroom model showed the path food takes during digestion.","example_zh":"教室模型展示食物在消化過程中經過的路徑。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/digestion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dilute-01-v1","level":"senior","word":"dilute","sort_order":1,"sense":"稀釋","alt_zh":"高中生把清水倒入藍色水彩顏料，攪拌後顏色變淡。","example":"We added water to dilute the blue paint.","example_zh":"我們加水稀釋藍色顏料。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dilute-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diplomacy-01-v1","level":"senior","word":"diplomacy","sort_order":1,"sense":"外交","alt_zh":"歷史展覽模型中，兩組成年外交代表在無字邊界地圖前和平協商。","example":"The museum exhibit showed how diplomacy helped settle the border dispute.","example_zh":"博物館展覽呈現外交如何幫助解決邊界爭議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diplomacy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-directive-01-v1","level":"senior","word":"directive","sort_order":1,"sense":"指令","alt_zh":"老師向高中生示意整理門口箱子，留出清楚通道。","example":"The safety directive required everyone to keep the doorway clear.","example_zh":"安全指令要求每個人保持門口暢通。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/directive-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disarmament-01-v1","level":"senior","word":"disarmament","sort_order":1,"sense":"裁軍","alt_zh":"博物館和平展覽中的成年代表，把象徵軍備的模型從桌上收進封箱，無戰鬥。","example":"The history class discussed disarmament as a way to reduce weapons.","example_zh":"歷史課討論透過裁軍減少武器。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disarmament-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disclaimer-01-v1","level":"senior","word":"disclaimer","sort_order":1,"sense":"免責聲明","alt_zh":"成年導覽員向高中生指出手冊開頭的小段說明，旁邊有步道模型，文字不可辨識。","example":"The guidebook included a disclaimer about possible changes to the walking routes.","example_zh":"導覽手冊附上關於步道路線可能變更的免責聲明。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disclaimer-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-discord-01-v1","level":"senior","word":"discord","sort_order":1,"sense":"不和","alt_zh":"原本意見不合的高中社團成員一起搬桌、合作布置活動，神情逐漸放鬆。","example":"The shared task helped resolve discord between the two clubs.","example_zh":"共同任務有助化解兩個社團的不和。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discord-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-discretion-01-v1","level":"senior","word":"discretion","sort_order":1,"sense":"審慎","alt_zh":"成年嚮導在安全地點仔細查看泥濘路面與天候，再向高中生說明路線。","example":"The guide used discretion when deciding whether the trail was safe.","example_zh":"嚮導審慎判斷步道是否安全。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discretion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disintegration-01-v1","level":"senior","word":"disintegration","sort_order":1,"sense":"瓦解","alt_zh":"檔案修復師戴手套，在工作桌上查看邊緣脆化碎裂的古老紙張。","example":"The old paper showed signs of disintegration along its edges.","example_zh":"舊紙張邊緣顯現逐漸碎裂的跡象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disintegration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dismissal-01-v1","level":"senior","word":"dismissal","sort_order":1,"sense":"解僱","alt_zh":"成年員工在安靜辦公室接過離職通知，管理員同情地說明，後方工廠已停工。","example":"The employee received notice of dismissal when the factory closed.","example_zh":"工廠關閉時，員工收到解僱通知。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dismissal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-displacement-01-v1","level":"senior","word":"displacement","sort_order":1,"sense":"流離","alt_zh":"帶著行李的家庭在安全臨時收容中心獲得床位與毛毯，無傷者。","example":"The flood caused the displacement of many families from their homes.","example_zh":"洪水使許多家庭被迫離家流離。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/displacement-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disposition-01-v1","level":"senior","word":"disposition","sort_order":1,"sense":"性情","alt_zh":"開朗的高中女生微笑邀請新同學坐在身旁，共同分享課本。","example":"Her cheerful disposition made new classmates feel welcome.","example_zh":"她開朗的性情讓新同學感到受歡迎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disposition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dissemination-01-v1","level":"senior","word":"dissemination","sort_order":1,"sense":"散布","alt_zh":"高中志工在圖書館分送只有活動圖畫的摺頁，向居民介紹節慶。","example":"The library helped with the dissemination of information about the festival.","example_zh":"圖書館幫忙傳播節慶資訊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dissemination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dissolution-01-v1","level":"senior","word":"dissolution","sort_order":1,"sense":"解散","alt_zh":"高中社團成員最後一次整理社團教室，把工具交給其他社團代表。","example":"The club's dissolution meant its tools had to be shared with other groups.","example_zh":"社團解散後，工具必須分給其他小組使用。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dissolution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-distortion-01-v1","level":"senior","word":"distortion","sort_order":1,"sense":"扭曲","alt_zh":"高中生在科學館彎曲鏡前，看著拉長變形的倒影開心微笑。","example":"The curved mirror caused a funny distortion of our reflections.","example_zh":"彎曲鏡面讓我們的倒影出現有趣的扭曲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/distortion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diversion-01-v1","level":"senior","word":"diversion","sort_order":1,"sense":"改道","alt_zh":"校車沿清楚的安全替代道路繞行，遠處受損橋梁入口已封閉。","example":"A road diversion led the school bus around the damaged bridge.","example_zh":"道路改道讓校車繞過受損橋梁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diversion-01-v1.webp","